SourceCode.Declaration:
public class METSalesOrderCancellationService extends METSysOperationService
{
    guid topPickingProcessId;

}

Method.Source:
public void initialise()
{
    METSalesOrderCancellationContract contract;

    super();

    contract = dataContract as METSalesOrderCancellationContract;

    // The dialog default of zero means one worker.
    threadCount = max(1, contract.parmThreadCount());
    topPickingProcessId = newGuid();

    this.buildQueue(contract.getQuery());
}

protected void initTaskDataContract(
    METSysOperationTaskDataContract _taskDataContract)
{
    METSalesOrderCancellationContract contract;

    super(_taskDataContract);

    contract = _taskDataContract as METSalesOrderCancellationContract;
    contract.parmProcessId(topPickingProcessId);
}

protected METSysOperationTaskDataContract taskDataContractObject()
{
    return new METSalesOrderCancellationContract();
}

private void buildQueue(Query _query)
{
    QueryRun queryRun;
    SalesTable salesTable;
    SalesLine salesLine;
    METSalesTable metSalesTable;
    METSalesLine metSalesLine;
    METSalesOrderCancellationQueue queueRecord;
    RecordInsertList queueList;
    Set queuedOrders;

    _query.allowCrossCompany(false);
    queryRun = new QueryRun(_query);
    queueList = new RecordInsertList(
        tableNum(METSalesOrderCancellationQueue));
    queuedOrders = new Set(Types::Int64);

    while (queryRun.next())
    {
        salesTable = queryRun.get(tableNum(SalesTable));
        salesLine = queryRun.get(tableNum(SalesLine));

        if (!salesTable.RecId
            || salesTable.DataAreaId != curExt()
            || queuedOrders.in(salesTable.RecId))
        {
            continue;
        }

        select firstOnly RecId, OrderCancellationRequired
            from metSalesTable
            where metSalesTable.SalesTable == salesTable.RecId;

        metSalesLine.clear();

        if (salesLine.RecId)
        {
            select firstOnly RecId, LineCancellationRequired
                from metSalesLine
                where metSalesLine.SalesLine == salesLine.RecId;
        }

        if ((metSalesTable.RecId
                && metSalesTable.OrderCancellationRequired == NoYes::Yes)
            || (metSalesLine.RecId
                && metSalesLine.LineCancellationRequired == NoYes::Yes))
        {
            queueRecord.clear();
            queueRecord.ProcessId = topPickingProcessId;
            queueRecord.SalesTableRecId = salesTable.RecId;
            queueRecord.SalesId = salesTable.SalesId;

            queueList.add(queueRecord);
            queuedOrders.add(salesTable.RecId);
        }
    }

    queueList.insertDatabase();
}
